1: //! Cyclic XOR de-scrambling and keystream application engine.
2: //!
3: //! Provides zero-allocation in-place de-scrambling (`descramble_in_place`), destination-slice
4: //! de-scrambling (`descramble_slice`), and allocating vector de-scrambling (`descramble_to_vec`)
5: //! for scrambled DJI record payloads.
6: 
7: use crate::crypto::crc64::derive_key;
8: use crate::error::FlightReaderError;
9: 
10: /// De-scrambles (or scrambles) `buf` in-place by cyclically applying the 8-byte `key`.
11: ///
12: /// Because XOR is an involutive operation ($A \oplus K \oplus K = A$), this function
13: /// is self-inverse: applying it twice with the same key restores the original bytes.
14: ///
15: /// Each byte `buf[i]` is mutated as `buf[i] ^= key[i % 8]`.
16: pub fn descramble_in_place(buf: &mut [u8], key: [u8; 8]) {
17:     for (i, b) in buf.iter_mut().enumerate() {
18:         *b ^= key[i % 8];
19:     }
20: }
21: 
22: /// De-scrambles (or scrambles) `src` into destination buffer `dst` using the cyclic 8-byte `key`.
23: ///
24: /// Returns `Ok(())` on success.
25: ///
26: /// # Errors
27: ///
28: /// Returns [`FlightReaderError::BufferOverflow`] if `dst.len() < src.len()`.
29: pub fn descramble_slice(src: &[u8], dst: &mut [u8], key: [u8; 8]) -> Result<(), FlightReaderError> {
30:     if dst.len() < src.len() {
31:         return Err(FlightReaderError::BufferOverflow {
32:             required: src.len(),
33:             capacity: dst.len(),
34:         });
35:     }
36: 
37:     for (i, (&s, d)) in src.iter().zip(dst.iter_mut()).enumerate() {
38:         *d = s ^ key[i % 8];
39:     }
40: 
41:     Ok(())
42: }
43: 
44: /// De-scrambles (or scrambles) `src` into a newly allocated [`Vec<u8>`] using cyclic 8-byte `key`.
45: #[must_use]
46: pub fn descramble_to_vec(src: &[u8], key: [u8; 8]) -> Vec<u8> {
47:     let mut out = Vec::with_capacity(src.len());
48:     for (i, &b) in src.iter().enumerate() {
49:         out.push(b ^ key[i % 8]);
50:     }
51:     out
52: }
53: 
54: /// De-scrambles a full record payload slice in-place, where `record_payload[0]` is the seed byte
55: /// and `record_payload[1..]` is the scrambled ciphertext.
56: ///
57: /// Derives the 8-byte key from `(record_type, seed)`, de-scrambles `record_payload[1..]` in-place,
58: /// and returns a mutable subslice to the recovered plaintext payload (`&mut record_payload[1..]`).
59: ///
60: /// # Errors
61: ///
62: /// Returns [`FlightReaderError::PayloadTooShort`] if `record_payload.len() < 2`.
63: pub fn descramble_record_in_place(
64:     record_payload: &mut [u8],
65:     record_type: u8,
66: ) -> Result<&mut [u8], FlightReaderError> {
67:     if record_payload.len() < 2 {
68:         return Err(FlightReaderError::PayloadTooShort {
69:             minimum: 2,
70:             available: record_payload.len(),
71:         });
72:     }
73: 
74:     let seed = record_payload[0];
75:     let key = derive_key(record_type, seed);
76:     descramble_in_place(&mut record_payload[1..], key);
77:     Ok(&mut record_payload[1..])
78: }
79: 
80: /// De-scrambles a full record payload slice into a newly allocated [`Vec<u8>`], where
81: /// `record_payload[0]` is the seed byte and `record_payload[1..]` is the scrambled ciphertext.
82: ///
83: /// # Errors
84: ///
85: /// Returns [`FlightReaderError::PayloadTooShort`] if `record_payload.len() < 2`.
86: pub fn descramble_record_to_vec(
87:     record_payload: &[u8],
88:     record_type: u8,
89: ) -> Result<Vec<u8>, FlightReaderError> {
90:     if record_payload.len() < 2 {
91:         return Err(FlightReaderError::PayloadTooShort {
92:             minimum: 2,
93:             available: record_payload.len(),
94:         });
95:     }
96: 
97:     let seed = record_payload[0];
98:     let key = derive_key(record_type, seed);
99:     Ok(descramble_to_vec(&record_payload[1..], key))
100: }
