11: /// Ground station application ecosystem identifying originating software.
12: ///
13: /// Extracted from byte offset 11 (`0x0B`) in the fixed header.
14: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
15: pub enum Department {
16:     /// Pre-production, unknown, or legacy testbed software (0).
17:     Unknown,
18:     /// DJI Mobile SDK custom enterprise applications (1).
19:     Sdk,
20:     /// DJI GO / DJI GO 4 mobile applications (2).
21:     DjiGo,
22:     /// DJI Fly consumer mobile application (3).
23:     DjiFly,
24:     /// DJI Agras / MG agricultural machinery app (4).
25:     AgriculturalMachinery,
26:     /// DJI Terra photogrammetry mapping workstation (5).
27:     Terra,
28:     /// DJI Pilot / DJI Pilot 2 enterprise ground station (7).
29:     DjiPilot,
30:     /// Ground Station Pro surveying application for iPadOS (8).
31:     GsPro,
32:     /// Fallback for unmapped or future department codes.
