11: /// Parsed fixed binary header from a DJI `.txt` mobile flight record.
12: ///
13: /// Every DJI flight telemetry log commences with either a 100-byte or 101-byte
14: /// header defining stream boundaries and metadata.
15: #[derive(Debug, Clone, PartialEq, Eq)]
16: pub struct TxtHeader {
17:     /// Byte offset where the details summary block (v1–v11) or telemetry records (v12–v14) reside.
18:     pub details_offset: i64,
19:     /// Declared header length in bytes (`100` or `101`).
20:     pub header_length: i16,
21:     /// Format major version number (`1` through `14`).
22:     pub version: u8,
23:     /// DJI ground station application ecosystem identifier.
24:     pub department: Department,
25:     /// Cryptographic status byte (`0` = plaintext, `!= 0` = scrambled / encrypted).
26:     pub scrambled_flag: u8,
27:     /// Reserved compatibility bytes (offsets 13 through 99, 87 bytes total).
28:     pub reserved: [u8; 87],
29:     /// Header padding byte present strictly when `header_length == 101` (offset 100).
30:     pub padding: Option<u8>,
31: }
